/**
 * Seed ~100 well-known companies per industry (10 industries = ~1000 total).
 * Idempotent: upserts by (userId, name).
 *
 * Run: npx ts-node src/scripts/seed-companies.ts
 * Env: OWNER_TELEGRAM_ID (optional) or uses first user in DB
 */

import dotenv from "dotenv";
dotenv.config();

import { prisma } from "../db/client";

interface CompanySeed {
  name: string;
  careersUrl: string;
  atsType: string;
  atsToken?: string;
  industry: string;
  continent: string;
  remoteFriendly: boolean;
}

function detectATS(url: string): { atsType: string; atsToken: string | null } {
  if (url.includes("greenhouse.io")) {
    const m = url.match(/greenhouse\.io\/([^/?#]+)/);
    return { atsType: "greenhouse", atsToken: m?.[1] ?? null };
  }
  if (url.includes("lever.co")) {
    const m = url.match(/lever\.co\/([^/?#]+)/);
    return { atsType: "lever", atsToken: m?.[1] ?? null };
  }
  if (url.includes("workable.com")) {
    const m = url.match(/workable\.com\/([^/?#]+)/);
    return { atsType: "workable", atsToken: m?.[1] ?? null };
  }
  if (url.includes("ashbyhq.com")) {
    const m = url.match(/ashbyhq\.com\/([^/?#]+)/);
    return { atsType: "ashby", atsToken: m?.[1] ?? null };
  }
  return { atsType: "careers_page", atsToken: null };
}

