async function main() {
  const targetTelegramId = process.env.OWNER_TELEGRAM_ID
    ? BigInt(process.env.OWNER_TELEGRAM_ID)
    : null;

  const user = targetTelegramId
    ? await prisma.user.findUnique({ where: { telegramId: targetTelegramId } })
    : await prisma.user.findFirst({ orderBy: { createdAt: "asc" } });

  if (!user) {
    console.error("No user found in DB. Sign in to the app first, then re-run.");
    process.exit(1);
  }

  console.log(`Seeding companies for user: ${user.name ?? user.email ?? user.id}\n`);

  const countByIndustry: Record<string, number> = {};
  let imported = 0;
  let skipped = 0;

  for (const row of COMPANIES) {
    const { atsType, atsToken } = detectATS(row.careersUrl);

    try {
      await prisma.followedCompany.upsert({
        where: { userId_name: { userId: user.id, name: row.name } },
        update: {
          atsType,
          atsToken,
          careersUrl:     row.careersUrl,
          industry:       row.industry,
          continent:      row.continent,
          remoteFriendly: row.remoteFriendly,
          desiredRoles:   "product designer",
        },
        create: {
          userId:         user.id,
          name:           row.name,
          atsType,
          atsToken,
          careersUrl:     row.careersUrl,
          industry:       row.industry,
          continent:      row.continent,
          remoteFriendly: row.remoteFriendly,
          desiredRoles:   "product designer",
        },
      });
      countByIndustry[row.industry] = (countByIndustry[row.industry] ?? 0) + 1;
      imported++;
    } catch (err: any) {
      console.log(`  ⚠️  ${row.name} — skipped: ${err.message}`);
      skipped++;
    }
  }

  console.log("Companies seeded by industry:");
  for (const [industry, count] of Object.entries(countByIndustry).sort()) {
    console.log(`  ${industry.padEnd(20)} ${count}`);
  }
  console.log(`\nTotal: ${imported} upserted, ${skipped} skipped.`);

  await prisma.$disconnect();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
